<?php
require_once __DIR__ . '/../core/db.php';
require_once __DIR__ . '/../core/functions.php';
require_once __DIR__ . '/../core/security.php';
require_once __DIR__ . '/../core/auth.php';
require_once __DIR__ . '/../core/csrf.php';
require_once __DIR__ . '/../core/rbac.php';
require_once __DIR__ . '/../core/inventory.php';

start_secure_session(); require_admin(); ensure_rbac_schema(); $u=require_menu_access('inventori','view'); ensure_inventory_module_schema();
$err=''; $branches=inventory_branches(); $products=db()->query("SELECT id,name,base_unit,sale_unit,sale_to_base_factor FROM products WHERE track_stock=1 ORDER BY name ASC")->fetchAll();
function collect_transfer_items(array $src): array { $ids=$src['item_product_id']??[]; $qtys=$src['item_qty']??[]; $notes=$src['item_notes']??[]; if(!is_array($ids))$ids=[]; if(!is_array($qtys))$qtys=[]; if(!is_array($notes))$notes=[]; $items=[]; $max=max(count($ids),count($qtys),count($notes)); for($i=0;$i<$max;$i++){ $pid=(int)($ids[$i]??0); $qty=parse_number_input($qtys[$i]??0); $note=trim((string)($notes[$i]??'')); if($pid<=0&&$qty<=0&&$note==='')continue; if($pid<=0||$qty<=0) throw new Exception('Item transfer tidak valid.'); $items[]=['product_id'=>$pid,'qty'=>$qty,'notes'=>$note]; } if(!$items) throw new Exception('Minimal 1 item transfer.'); return $items; }
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_check(); $action=(string)($_POST['action']??'create');
 try{ $db=db();
  if($action==='create'){
    require_action_access('inventori','create'); $no=trim((string)($_POST['transfer_no']??'')); $date=(string)($_POST['transfer_date']??date('Y-m-d')); $src=(int)($_POST['source_branch_id']??0); $dst=(int)($_POST['dest_branch_id']??0); $notes=trim((string)($_POST['notes']??'')); $items=collect_transfer_items($_POST);
    if($no==='') throw new Exception('Nomor transfer wajib.'); if($src<=0||$dst<=0||$src===$dst) throw new Exception('Sumber dan tujuan transfer harus berbeda.');
    $db->beginTransaction(); $stmt=$db->prepare("INSERT INTO stock_transfer_headers (transfer_no,transfer_date,source_branch_id,dest_branch_id,status,notes,created_by) VALUES (?,?,?,?, 'draft',?,?)"); $stmt->execute([$no,$date,$src,$dst,$notes,(int)($u['id']??0)]); $tid=(int)$db->lastInsertId();
    $ins=$db->prepare("INSERT INTO stock_transfer_items (transfer_id,product_id,qty,notes) VALUES (?,?,?,?)"); foreach($items as $it)$ins->execute([$tid,$it['product_id'],$it['qty'],$it['notes']]); $db->commit(); redirect(base_url('admin/stock_transfers.php'));
  }
  if($action==='send'){
    require_action_access('inventori','edit'); $id=(int)($_POST['id']??0); $db->beginTransaction(); $stmt=$db->prepare("SELECT * FROM stock_transfer_headers WHERE id=? LIMIT 1 FOR UPDATE"); $stmt->execute([$id]); $h=$stmt->fetch(); if(!$h) throw new Exception('Transfer tidak ditemukan.'); if($h['status']!=='draft') throw new Exception('Hanya draft yang bisa dikirim.');
    $stmt=$db->prepare("SELECT ti.*, p.sale_to_base_factor FROM stock_transfer_items ti JOIN products p ON p.id=ti.product_id WHERE ti.transfer_id=?"); $stmt->execute([$id]); foreach($stmt->fetchAll() as $it){ add_stock_ledger(['branch_id'=>(int)$h['source_branch_id'],'product_id'=>(int)$it['product_id'],'trans_type'=>'transfer_send','ref_table'=>'stock_transfer_headers','ref_id'=>$id,'qty_in'=>0,'qty_out'=>(float)$it['qty']*max(0.000001,(float)($it['sale_to_base_factor']??1)),'unit_cost'=>null,'note'=>'Kirim transfer stok','created_by'=>(int)($u['id']??0)]); }
    $db->prepare("UPDATE stock_transfer_headers SET status='sent', sent_by=?, sent_at=NOW() WHERE id=?")->execute([(int)($u['id']??0),$id]); $db->commit(); redirect(base_url('admin/stock_transfers.php'));
  }
  if($action==='receive'){
    require_action_access('inventori','edit'); $id=(int)($_POST['id']??0); $db->beginTransaction(); $stmt=$db->prepare("SELECT * FROM stock_transfer_headers WHERE id=? LIMIT 1 FOR UPDATE"); $stmt->execute([$id]); $h=$stmt->fetch(); if(!$h) throw new Exception('Transfer tidak ditemukan.'); if($h['status']!=='sent') throw new Exception('Hanya transfer sent yang bisa diterima.');
    $stmt=$db->prepare("SELECT ti.*, p.sale_to_base_factor FROM stock_transfer_items ti JOIN products p ON p.id=ti.product_id WHERE ti.transfer_id=?"); $stmt->execute([$id]); foreach($stmt->fetchAll() as $it){ add_stock_ledger(['branch_id'=>(int)$h['dest_branch_id'],'product_id'=>(int)$it['product_id'],'trans_type'=>'transfer_receive','ref_table'=>'stock_transfer_headers','ref_id'=>$id,'qty_in'=>(float)$it['qty']*max(0.000001,(float)($it['sale_to_base_factor']??1)),'qty_out'=>0,'unit_cost'=>null,'note'=>'Terima transfer stok','created_by'=>(int)($u['id']??0)]); }
    $db->prepare("UPDATE stock_transfer_headers SET status='received', received_by=?, received_at=NOW() WHERE id=?")->execute([(int)($u['id']??0),$id]); $db->commit(); redirect(base_url('admin/stock_transfers.php'));
  }
  if($action==='cancel'){
    require_action_access('inventori','delete'); $id=(int)($_POST['id']??0); $db->beginTransaction(); $stmt=$db->prepare("SELECT * FROM stock_transfer_headers WHERE id=? LIMIT 1 FOR UPDATE"); $stmt->execute([$id]); $h=$stmt->fetch(); if(!$h) throw new Exception('Transfer tidak ditemukan.'); if($h['status']!=='draft') throw new Exception('Hanya draft yang bisa dicancel.'); $db->prepare("UPDATE stock_transfer_headers SET status='cancelled' WHERE id=?")->execute([$id]); $db->commit(); redirect(base_url('admin/stock_transfers.php'));
  }
 }catch(Throwable $e){ if(isset($db)&&$db->inTransaction())$db->rollBack(); $err=$e->getMessage(); }
}
$rows=db()->query("SELECT h.*, sb.branch_name source_name, dbb.branch_name dest_name FROM stock_transfer_headers h JOIN branches sb ON sb.id=h.source_branch_id JOIN branches dbb ON dbb.id=h.dest_branch_id ORDER BY h.id DESC LIMIT 100")->fetchAll(); $customCss=setting('custom_css','');
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Transfer Stok</title><link rel="icon" href="<?php echo e(favicon_url()); ?>"><link rel="stylesheet" href="<?php echo e(asset_url('assets/app.css')); ?>"><style><?php echo $customCss; ?></style></head><body><div class="container"><?php include __DIR__.'/partials_sidebar.php'; ?><div class="main"><div class="topbar"><button class="btn" data-toggle-sidebar type="button">Menu</button></div><div class="content"><div class="card"><h3>Transfer Stok Dapur/Cabang ke Toko</h3><p><small>Gunakan alur ini untuk stok masuk toko dari dapur. Stok tujuan baru bertambah setelah tombol Terima ditekan.</small></p><?php if($err): ?><div class="card" style="border-color:rgba(251,113,133,.35);background:rgba(251,113,133,.10)"><?php echo e($err); ?></div><?php endif; ?><form method="post"><input type="hidden" name="_csrf" value="<?php echo e(csrf_token()); ?>"><input type="hidden" name="action" value="create"><div class="grid cols-2"><div class="row"><label>No Transfer</label><input name="transfer_no" required value="<?php echo e('TRF-'.date('YmdHis')); ?>"></div><div class="row"><label>Tanggal</label><input type="date" name="transfer_date" required value="<?php echo e(date('Y-m-d')); ?>"></div></div><div class="grid cols-2"><div class="row"><label>Dari Dapur/Cabang</label><select name="source_branch_id"><?php foreach($branches as $b): ?><option value="<?php echo e((string)$b['id']); ?>"><?php echo e($b['branch_name']); ?></option><?php endforeach; ?></select></div><div class="row"><label>Ke Toko/Cabang</label><select name="dest_branch_id"><?php foreach($branches as $b): ?><option value="<?php echo e((string)$b['id']); ?>" <?php echo (int)$b['id']===active_branch_id()?'selected':''; ?>><?php echo e($b['branch_name']); ?></option><?php endforeach; ?></select></div></div><div class="row"><label>Catatan</label><textarea name="notes" rows="2"></textarea></div><table class="table" id="items-table"><thead><tr><th>Produk</th><th style="width:130px">Qty</th><th>Catatan</th><th>Aksi</th></tr></thead><tbody><tr class="item-row"><td><select name="item_product_id[]" required><option value="">- pilih produk -</option><?php foreach($products as $p): ?><option value="<?php echo e((string)$p['id']); ?>"><?php echo e($p['name']); ?></option><?php endforeach; ?></select></td><td><input type="number" step="0.0001" min="0.0001" name="item_qty[]" value="1" required></td><td><input name="item_notes[]"></td><td><button class="btn danger btn-remove-item" type="button">Hapus</button></td></tr></tbody></table><button class="btn" id="btn-add-item" type="button">Tambah Item</button> <button class="btn" type="submit">Simpan Draft</button></form></div><div class="card"><h3>Riwayat Transfer</h3><table class="table"><thead><tr><th>No</th><th>Tanggal</th><th>Dari</th><th>Ke</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?php echo e($r['transfer_no']); ?></td><td><?php echo e($r['transfer_date']); ?></td><td><?php echo e($r['source_name']); ?></td><td><?php echo e($r['dest_name']); ?></td><td><?php echo e($r['status']); ?></td><td style="display:flex;gap:6px;flex-wrap:wrap"><?php foreach(['send'=>'Kirim','receive'=>'Terima','cancel'=>'Cancel'] as $act=>$label): ?><?php if(($act==='send'&&$r['status']==='draft')||($act==='receive'&&$r['status']==='sent')||($act==='cancel'&&$r['status']==='draft')): ?><form method="post"><input type="hidden" name="_csrf" value="<?php echo e(csrf_token()); ?>"><input type="hidden" name="action" value="<?php echo e($act); ?>"><input type="hidden" name="id" value="<?php echo e((string)$r['id']); ?>"><button class="btn <?php echo $act==='cancel'?'danger':''; ?>"><?php echo e($label); ?></button></form><?php endif; ?><?php endforeach; ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></div><script>(function(){const tb=document.querySelector('#items-table tbody'),add=document.querySelector('#btn-add-item');function bind(r){r.querySelector('.btn-remove-item').addEventListener('click',()=>{if(tb.querySelectorAll('.item-row').length<=1){alert('Minimal 1 item.');return;}r.remove();});}tb.querySelectorAll('.item-row').forEach(bind);add.addEventListener('click',()=>{const c=tb.querySelector('.item-row').cloneNode(true);c.querySelector('select').value='';c.querySelector('[name="item_qty[]"]').value='1';c.querySelector('[name="item_notes[]"]').value='';tb.appendChild(c);bind(c);});})();</script><script defer src="<?php echo e(asset_url('assets/app.js')); ?>"></script></body></html>
